-- InsightPulse data-only seed. Load after database/schema.sql into an EMPTY schema:
--   psql "$DATABASE_URL" -f database/schema.sql && psql "$DATABASE_URL" -f <this file>
SET client_encoding = 'UTF8';
BEGIN;
TRUNCATE action_status_events, action_evidence, action_items, state_change_events, data_quality_issues, feedback_themes, sentiment_predictions, feedback_annotations, feedback_items, pipeline_runs, support_messages, support_tickets, reviews, survey_responses, surveys, customers, products, channels, themes, sentiment_labels CASCADE;




















SELECT setval('pipeline_run_seq', COALESCE((SELECT max(substring(run_id from '[0-9]+$')::bigint) FROM pipeline_runs), 1));
SELECT setval('action_item_seq', COALESCE((SELECT max(substring(action_id from '[0-9]+$')::bigint) FROM action_items), 1));
SELECT setval('dq_issue_seq', COALESCE((SELECT max(substring(issue_id from '[0-9]+$')::bigint) FROM data_quality_issues), 1));
SELECT setval(pg_get_serial_sequence('sentiment_predictions', 'prediction_id'), COALESCE((SELECT max(prediction_id) FROM sentiment_predictions), 1));
SELECT setval(pg_get_serial_sequence('feedback_themes', 'feedback_theme_id'), COALESCE((SELECT max(feedback_theme_id) FROM feedback_themes), 1));
SELECT setval(pg_get_serial_sequence('action_status_events', 'event_id'), COALESCE((SELECT max(event_id) FROM action_status_events), 1));
SELECT setval(pg_get_serial_sequence('state_change_events', 'event_id'), COALESCE((SELECT max(event_id) FROM state_change_events), 1));
COMMIT;
